// Antwort auswerten, Produkte + Varianten in staticData sammeln,
// Buch/Merch-Flag setzen, nächsten Cursor weitergeben.
const resp = $input.first().json;
const prev = $('Config + Array leeren').item.json;
const config = prev.config;
const productsConn = resp?.data?.products;
const edges = productsConn?.edges || [];
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.produkte)) staticData.produkte = [];

// Gutscheine erkennen: Shopify-Flag isGiftCard ODER Titel (Gross-/Kleinschreibung egal)
const GUTSCHEIN_TITEL = 'geschenkgutschein';

// Uebersprungene Varianten nur merken (fuer die Dry-Run-Vorschau), geschrieben wird davon nichts
if (!Array.isArray(staticData.uebersprungen)) staticData.uebersprungen = [];
const merkeUebersprungen = (node, grund) => {
  for (const ve of (node.variants?.edges || [])) {
    staticData.uebersprungen.push({ variantId: ve.node.id, title: node.title, sku: ve.node.sku, grund: grund, priceDEBrutto: parseFloat(ve.node.price) });
  }
};

for (const e of edges) {
  const node = e.node;
  // Bundles NIE anfassen -> überspringen (werden händisch gepflegt)
  if (node.inBundle) { merkeUebersprungen(node, 'bundle'); continue; }

  // Gutscheine NIE anfassen -> überspringen (Gutscheinwert wird nicht umgerechnet)
  if (node.isGiftCard || String(node.title || '').trim().toLowerCase() === GUTSCHEIN_TITEL) {
    merkeUebersprungen(node, 'gutschein');
    continue;
  }

  // Typ bestimmen: Buch hat Vorrang, sonst Merch. Alles andere -> Fallback = Merch-Rate.
  let typ;
  if (node.inBuecher) typ = 'buch';
  else typ = 'merch'; // Merch UND Fallback (keiner der Collections)

  for (const ve of (node.variants?.edges || [])) {
    const v = ve.node;
    const priceDE = parseFloat(v.price);
    if (!isFinite(priceDE)) continue;
    // Streichpreis nur übernehmen, wenn er wirklich über dem VK liegt (sonst kein Rabatt)
    const vglDE = parseFloat(v.compareAtPrice);
    staticData.produkte.push({
      variantId: v.id,
      productId: node.id,
      title: node.title,
      sku: v.sku,
      typ: typ,
      priceDEBrutto: priceDE,
      compareAtDEBrutto: (isFinite(vglDE) && vglDE > priceDE) ? vglDE : null
    });
  }
}
const hasNext = !!productsConn?.pageInfo?.hasNextPage;
const endCursor = productsConn?.pageInfo?.endCursor || null;
return [{
  json: {
    accessToken: prev.accessToken,
    config: config,
    cursor: endCursor,
    hasNext: hasNext,
    gesammelt: staticData.produkte.length
  }
}];

// Schleife: nächste Seite anfordern (Token bleibt gültig innerhalb Laufzeit).
const prev = $input.first().json;
return [{
  json: {
    accessToken: prev.accessToken,
    config: prev.config,
    cursor: prev.cursor,
    hasNext: prev.hasNext
  }
}];

// Nach Pagination: alle gesammelten Produkte holen und AT/CH-Bruttopreise berechnen.
// Weg: DE-Brutto -> Netto (÷ DE-Satz je Typ) -> Zielland-Brutto (× Zielsatz je Typ).
// Der Streichpreis (compareAtPrice) laeuft denselben Weg.
const config = $('Config + Array leeren').first().json.config;
const staticData = $getWorkflowStaticData('global');
const produkte = staticData.produkte || [];

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

// Streichpreis umrechnen. Liegt er nach dem Runden nicht mehr ueber dem Zielpreis,
// entfaellt er (null = kein Streichpreis im Zielland).
const streichpreis = (vglDE, deSatz, zielSatz, zielPreis) => {
  if (vglDE === null || vglDE === undefined) return null;
  const vgl = round2(vglDE / (1 + deSatz) * (1 + zielSatz));
  return vgl > zielPreis ? vgl : null;
};

const out = produkte.map((p) => {
  const deSatz = config.tax.DE[p.typ];
  const netto = p.priceDEBrutto / (1 + deSatz);

  const atSatz = config.tax.AT[p.typ];
  const chSatz = config.tax.CH[p.typ];

  const priceAT = round2(netto * (1 + atSatz));
  const priceCH = round2(netto * (1 + chSatz));

  const compareAtAT = streichpreis(p.compareAtDEBrutto, deSatz, atSatz, priceAT);
  const compareAtCH = streichpreis(p.compareAtDEBrutto, deSatz, chSatz, priceCH);

  return {
    json: {
      variantId: p.variantId,
      title: p.title,
      sku: p.sku,
      typ: p.typ,
      priceDEBrutto: round2(p.priceDEBrutto),
      netto: round2(netto),
      priceAT: priceAT,
      priceCH: priceCH,
      compareAtDEBrutto: (p.compareAtDEBrutto === null || p.compareAtDEBrutto === undefined) ? null : round2(p.compareAtDEBrutto),
      compareAtAT: compareAtAT,
      compareAtCH: compareAtCH
    }
  };
});

return out;

// Flache Preis-Liste für AT bauen (Batching übernimmt Split in Batches)
const config = $('Config + Array leeren').first().json.config;
const items = $('Preise berechnen (AT + CH)').all();

const currency = config.priceLists.AT.currency;
const priceListId = config.priceLists.AT.id;

return items.map(i => ({
  json: {
    accessToken: $('Config + Array leeren').first().json.accessToken,
    config: config,
    priceListId: priceListId,
    variantId: i.json.variantId,
    sku: i.json.sku,
    price: { amount: i.json.priceAT.toFixed(2), currencyCode: currency },
    // null = kein Streichpreis in AT (ein alter Streichpreis wird damit ueberschrieben)
    compareAtPrice: (i.json.compareAtAT === null || i.json.compareAtAT === undefined)
      ? null
      : { amount: i.json.compareAtAT.toFixed(2), currencyCode: currency }
  }
}));

