// Preise dieser Seite in den Bestand schreiben und den naechsten Schleifenschritt bestimmen:
// weitere Seite -> gleiche Preisliste, sonst AT -> CH, danach fertig.
const resp = $input.first().json;
const prev = $('Config + Array leeren').first().json;
const config = prev.config;
const sd = $getWorkflowStaticData('global');

const land = (sd.bestandState && sd.bestandState.land) || 'AT';
if (!sd.bestand) sd.bestand = { AT: {}, CH: {} };
if (!sd.bestand[land]) sd.bestand[land] = {};
if (!sd.bestandVgl) sd.bestandVgl = { AT: {}, CH: {} };
if (!sd.bestandVgl[land]) sd.bestandVgl[land] = {};

const conn = resp?.data?.priceList?.prices;
for (const e of (conn?.edges || [])) {
  const vid = e?.node?.variant?.id;
  if (!vid) continue;
  const amount = parseFloat(e?.node?.price?.amount);
  if (!isFinite(amount)) continue;
  sd.bestand[land][vid] = amount;
  // Streichpreis getrennt ablegen (null = in der Preisliste keiner hinterlegt)
  const vgl = parseFloat(e?.node?.compareAtPrice?.amount);
  sd.bestandVgl[land][vid] = isFinite(vgl) ? vgl : null;
}

// GraphQL-Fehler (z. B. fehlender Scope) nicht verschlucken -> landen im Report.
for (const e of (resp?.errors || [])) {
  sd.bestandFehler = (sd.bestandFehler || []).concat([land + ': ' + (e.message || 'unbekannter GraphQL-Fehler')]);
}

let nextLand = land;
let nextCursor = conn?.pageInfo?.endCursor || null;
let fertig = false;

if (conn?.pageInfo?.hasNextPage) {
  // gleiche Preisliste, naechste Seite
} else if (land === 'AT') {
  nextLand = 'CH';
  nextCursor = null;
} else {
  fertig = true;
}

sd.bestandState = { land: nextLand, cursor: nextCursor };

return [{
  json: {
    accessToken: prev.accessToken,
    config: config,
    land: nextLand,
    priceListId: config.priceLists[nextLand].id,
    cursor: nextCursor,
    bestandFertig: fertig,
    gelesenAT: Object.keys(sd.bestand.AT || {}).length,
    gelesenCH: Object.keys(sd.bestand.CH || {}).length
  }
}];

// Neu berechnete Preise gegen den ausgelesenen Bestand halten.
// Ergebnis (staticData.changes/stats) ist die Datenbasis des Abschluss-Reports.
// Geschrieben wird weiterhin alles - hier wird nur klassifiziert.
const prev = $('Config + Array leeren').first().json;
const config = prev.config;
const sd = $getWorkflowStaticData('global');
const bestand = sd.bestand || { AT: {}, CH: {} };
const bestandVgl = sd.bestandVgl || { AT: {}, CH: {} };
const neu = $('Preise berechnen (AT + CH)').all().map(i => i.json);

// Centgenau vergleichen (Rundungsrauschen ignorieren)
const gleich = (alt, neuPreis) => Math.abs(alt - neuPreis) < 0.005;

// Streichpreise: undefined/null = keiner. Beide leer = gleich, nur einer leer = abweichend.
const leer = (v) => (v === undefined || v === null) ? null : v;
const gleichVgl = (a, b) => (a === null || b === null) ? a === b : gleich(a, b);

const changes = [];
const stats = {
  AT: { geprueft: 0, neu: 0, geaendert: 0, unveraendert: 0 },
  CH: { geprueft: 0, neu: 0, geaendert: 0, unveraendert: 0 }
};

for (const p of neu) {
  const altAT = bestand.AT ? bestand.AT[p.variantId] : undefined;
  const altCH = bestand.CH ? bestand.CH[p.variantId] : undefined;

  const altVglAT = bestandVgl.AT ? leer(bestandVgl.AT[p.variantId]) : null;
  const altVglCH = bestandVgl.CH ? leer(bestandVgl.CH[p.variantId]) : null;
  const neuVglAT = leer(p.compareAtAT);
  const neuVglCH = leer(p.compareAtCH);

  // geaendert = VK ODER Streichpreis weicht ab
  const statusAT = altAT === undefined ? 'neu'
    : ((gleich(altAT, p.priceAT) && gleichVgl(altVglAT, neuVglAT)) ? 'unveraendert' : 'geaendert');
  const statusCH = altCH === undefined ? 'neu'
    : ((gleich(altCH, p.priceCH) && gleichVgl(altVglCH, neuVglCH)) ? 'unveraendert' : 'geaendert');

  stats.AT.geprueft++;
  stats.CH.geprueft++;
  stats.AT[statusAT]++;
  stats.CH[statusCH]++;

  if (statusAT !== 'unveraendert' || statusCH !== 'unveraendert') {
    changes.push({
      variantId: p.variantId,
      sku: p.sku || '',
      title: p.title,
      typ: p.typ,
      priceDEBrutto: p.priceDEBrutto,
      compareAtDEBrutto: leer(p.compareAtDEBrutto),
      altAT: altAT === undefined ? null : altAT,
      neuAT: p.priceAT,
      altVglAT: altVglAT,
      neuVglAT: neuVglAT,
      statusAT: statusAT,
      altCH: altCH === undefined ? null : altCH,
      neuCH: p.priceCH,
      altVglCH: altVglCH,
      neuVglCH: neuVglCH,
      statusCH: statusCH
    });
  }
}

sd.changes = changes;
sd.stats = stats;

return [{
  json: {
    accessToken: prev.accessToken,
    config: config,
    aenderungen: changes.length,
    stats: stats
  }
}];

// Shopify-Antwort dieses Batches auswerten: geschriebene Preise zaehlen, Fehler sammeln.
// Wandert in staticData, weil die Schleife viele Laeufe hat.
const resp = $input.first().json;
const sd = $getWorkflowStaticData('global');

if (!sd.report) sd.report = {};
if (!sd.report.AT) sd.report.AT = { batches: 0, geschrieben: 0, fehler: [] };
const r = sd.report.AT;

const res = resp?.data?.priceListFixedPricesUpdate;
r.batches++;
r.geschrieben += (res?.pricesAdded || []).length;

for (const e of (res?.userErrors || [])) {
  r.fehler.push({
    batch: r.batches,
    code: e.code || '',
    feld: Array.isArray(e.field) ? e.field.join('.') : (e.field || ''),
    meldung: e.message || ''
  });
}
for (const e of (resp?.errors || [])) {
  r.fehler.push({ batch: r.batches, code: 'GRAPHQL', feld: '', meldung: e.message || '' });
}

return $input.all();

// Shopify-Antwort dieses Batches auswerten: geschriebene Preise zaehlen, Fehler sammeln.
// Wandert in staticData, weil die Schleife viele Laeufe hat.
const resp = $input.first().json;
const sd = $getWorkflowStaticData('global');

if (!sd.report) sd.report = {};
if (!sd.report.CH) sd.report.CH = { batches: 0, geschrieben: 0, fehler: [] };
const r = sd.report.CH;

const res = resp?.data?.priceListFixedPricesUpdate;
r.batches++;
r.geschrieben += (res?.pricesAdded || []).length;

for (const e of (res?.userErrors || [])) {
  r.fehler.push({
    batch: r.batches,
    code: e.code || '',
    feld: Array.isArray(e.field) ? e.field.join('.') : (e.field || ''),
    meldung: e.message || ''
  });
}
for (const e of (resp?.errors || [])) {
  r.fehler.push({ batch: r.batches, code: 'GRAPHQL', feld: '', meldung: e.message || '' });
}

return $input.all();

// Sammelpunkt: die AT-Schleife ist durch. Ein Item, damit der Merge zuendet.
const sd = $getWorkflowStaticData('global');
const r = (sd.report && sd.report.AT) || { batches: 0, geschrieben: 0, fehler: [] };
return [{ json: { land: 'AT', batches: r.batches, geschrieben: r.geschrieben, fehler: r.fehler.length } }];

// Sammelpunkt: die CH-Schleife ist durch. Ein Item, damit der Merge zuendet.
const sd = $getWorkflowStaticData('global');
const r = (sd.report && sd.report.CH) || { batches: 0, geschrieben: 0, fehler: [] };
return [{ json: { land: 'CH', batches: r.batches, geschrieben: r.geschrieben, fehler: r.fehler.length } }];

// Abschluss-Report ueber beide Kataloge (AT + CH).
// Quelle: staticData.changes/stats (Vergleich vor dem Schreiben) + staticData.report (Shopify-Antworten).
const sd = $getWorkflowStaticData('global');
const prev = $('Config + Array leeren').first().json;
const config = prev.config;

const changes = sd.changes || [];
const stats = sd.stats || {
  AT: { geprueft: 0, neu: 0, geaendert: 0, unveraendert: 0 },
  CH: { geprueft: 0, neu: 0, geaendert: 0, unveraendert: 0 }
};
const rAT = (sd.report && sd.report.AT) || { batches: 0, geschrieben: 0, fehler: [] };
const rCH = (sd.report && sd.report.CH) || { batches: 0, geschrieben: 0, fehler: [] };
const bestandFehler = sd.bestandFehler || [];
const gelesenAT = Object.keys((sd.bestand && sd.bestand.AT) || {}).length;
const gelesenCH = Object.keys((sd.bestand && sd.bestand.CH) || {}).length;

const wAT = config.priceLists.AT.currency;
const wCH = config.priceLists.CH.currency;

const start = sd.startedAt ? new Date(sd.startedAt) : null;
const ende = new Date();
const dauerMin = start ? Math.round((ende - start) / 600) / 100 : null;
const datumDe = ende.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const stempel = ende.toISOString().slice(0, 10);

const esc = (s) => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const geld = (n, w) => (n === null || n === undefined)
  ? '&ndash;' : Number(n).toFixed(2).replace('.', ',') + ' ' + w;
const zahl = (n) => Number(n || 0).toLocaleString('de-DE');

// Sortierung: neu aufgenommene Varianten zuerst, danach groesste Preisdifferenz.
const delta = (c) => (c.altAT === null ? 0 : Math.abs(c.neuAT - c.altAT))
                   + (c.altCH === null ? 0 : Math.abs(c.neuCH - c.altCH));
const sortiert = changes.slice().sort((a, b) => {
  const aNeu = (a.statusAT === 'neu' || a.statusCH === 'neu') ? 1 : 0;
  const bNeu = (b.statusAT === 'neu' || b.statusCH === 'neu') ? 1 : 0;
  if (aNeu !== bNeu) return bNeu - aNeu;
  return delta(b) - delta(a);
});

// ===== CSV (vollstaendige Liste, als Anhang) =====
const csvFeld = (v) => {
  const s = String(v === null || v === undefined ? '' : v);
  return /[";\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
};
const csvZahl = (n) => (n === null || n === undefined) ? '' : Number(n).toFixed(2).replace('.', ',');
const csvKopf = ['SKU', 'Titel', 'Typ', 'DE Brutto', 'DE Streichpreis',
  'AT alt', 'AT neu', 'AT Streichpreis alt', 'AT Streichpreis neu', 'AT Status',
  'CH alt', 'CH neu', 'CH Streichpreis alt', 'CH Streichpreis neu', 'CH Status', 'Variant-ID'];
const csvZeilen = sortiert.map(c => [
  c.sku, c.title, c.typ, csvZahl(c.priceDEBrutto), csvZahl(c.compareAtDEBrutto),
  csvZahl(c.altAT), csvZahl(c.neuAT), csvZahl(c.altVglAT), csvZahl(c.neuVglAT), c.statusAT,
  csvZahl(c.altCH), csvZahl(c.neuCH), csvZahl(c.altVglCH), csvZahl(c.neuVglCH), c.statusCH,
  c.variantId
].map(csvFeld).join(';'));
const csv = '﻿' + [csvKopf.join(';')].concat(csvZeilen).join('\r\n') + '\r\n';

// ===== HTML =====
const TD = 'padding:6px 10px;border-bottom:1px solid #e8eaed;font-size:13px;';
const TH = 'padding:6px 10px;border-bottom:2px solid #d2d5da;font-size:12px;text-align:left;color:#5f6368;text-transform:uppercase;letter-spacing:.04em;';

const preisZelle = (alt, neuPreis, status, waehrung) => {
  if (status === 'unveraendert') return '<span style="color:#9aa0a6">' + geld(neuPreis, waehrung) + '</span>';
  if (status === 'neu') return '<span style="color:#1a73e8">neu: <b>' + geld(neuPreis, waehrung) + '</b></span>';
  // nur der Streichpreis weicht ab -> VK neutral anzeigen
  if (Math.abs(alt - neuPreis) < 0.005) return '<span>' + geld(neuPreis, waehrung) + '</span>';
  const farbe = neuPreis > alt ? '#c5221f' : '#137333';
  return '<span style="color:#80868b">' + geld(alt, waehrung) + '</span> &rarr; <b style="color:' + farbe + '">' + geld(neuPreis, waehrung) + '</b>';
};

// Streichpreis-Zeile unter dem VK (nur wenn alt oder neu einer hinterlegt ist)
const vglZusatz = (altVgl, neuVgl, status, waehrung) => {
  const a = (altVgl === null || altVgl === undefined) ? null : altVgl;
  const n = (neuVgl === null || neuVgl === undefined) ? null : neuVgl;
  if (a === null && n === null) return '';
  const f = (v) => v === null ? 'keiner' : '<s>' + geld(v, waehrung) + '</s>';
  const gleichVgl = a !== null && n !== null && Math.abs(a - n) < 0.005;
  const inhalt = (status === 'neu' || gleichVgl) ? f(n) : f(a) + ' &rarr; <b>' + f(n) + '</b>';
  return '<br><span style="color:#80868b;font-size:12px">Streichpreis: ' + inhalt + '</span>';
};
const vglDE = (v) => (v === null || v === undefined) ? ''
  : '<br><span style="color:#80868b;font-size:12px"><s>' + geld(v, 'EUR') + '</s></span>';

const MAX_ZEILEN = 200;
const zeilen = sortiert.slice(0, MAX_ZEILEN).map(c =>
  '<tr>'
  + '<td style="' + TD + 'font-family:monospace">' + esc(c.sku || '–') + '</td>'
  + '<td style="' + TD + '">' + esc(c.title) + '</td>'
  + '<td style="' + TD + 'color:#5f6368">' + esc(c.typ) + '</td>'
  + '<td style="' + TD + 'text-align:right;white-space:nowrap">' + geld(c.priceDEBrutto, 'EUR') + vglDE(c.compareAtDEBrutto) + '</td>'
  + '<td style="' + TD + 'white-space:nowrap">' + preisZelle(c.altAT, c.neuAT, c.statusAT, wAT) + vglZusatz(c.altVglAT, c.neuVglAT, c.statusAT, wAT) + '</td>'
  + '<td style="' + TD + 'white-space:nowrap">' + preisZelle(c.altCH, c.neuCH, c.statusCH, wCH) + vglZusatz(c.altVglCH, c.neuVglCH, c.statusCH, wCH) + '</td>'
  + '</tr>'
).join('');

const summeZeile = (land, s, r, gelesen, waehrung) =>
  '<tr>'
  + '<td style="' + TD + '"><b>' + land + '</b> <span style="color:#80868b">(' + waehrung + ')</span></td>'
  + '<td style="' + TD + 'text-align:right">' + zahl(s.geprueft) + '</td>'
  + '<td style="' + TD + 'text-align:right"><b>' + zahl(s.geaendert) + '</b></td>'
  + '<td style="' + TD + 'text-align:right">' + zahl(s.neu) + '</td>'
  + '<td style="' + TD + 'text-align:right;color:#80868b">' + zahl(s.unveraendert) + '</td>'
  + '<td style="' + TD + 'text-align:right">' + zahl(gelesen) + '</td>'
  + '<td style="' + TD + 'text-align:right">' + zahl(r.geschrieben) + ' <span style="color:#80868b">/ ' + zahl(r.batches) + ' Batches</span></td>'
  + '<td style="' + TD + 'text-align:right;' + (r.fehler.length ? 'color:#c5221f;font-weight:bold' : 'color:#80868b') + '">' + zahl(r.fehler.length) + '</td>'
  + '</tr>';

const alleFehler = []
  .concat(rAT.fehler.map(f => Object.assign({ land: 'AT' }, f)))
  .concat(rCH.fehler.map(f => Object.assign({ land: 'CH' }, f)));

const fehlerBlock = alleFehler.length
  ? '<h3 style="font:600 15px/1.4 Arial,sans-serif;color:#c5221f;margin:28px 0 8px">Fehler beim Schreiben (' + alleFehler.length + ')</h3>'
    + '<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%">'
    + '<tr><th style="' + TH + '">Katalog</th><th style="' + TH + '">Batch</th><th style="' + TH + '">Code</th><th style="' + TH + '">Feld</th><th style="' + TH + '">Meldung</th></tr>'
    + alleFehler.slice(0, 50).map(f =>
        '<tr><td style="' + TD + '">' + esc(f.land) + '</td><td style="' + TD + '">' + esc(f.batch) + '</td>'
        + '<td style="' + TD + 'font-family:monospace">' + esc(f.code) + '</td><td style="' + TD + 'font-family:monospace">' + esc(f.feld) + '</td>'
        + '<td style="' + TD + '">' + esc(f.meldung) + '</td></tr>').join('')
    + '</table>'
    + (alleFehler.length > 50 ? '<p style="font:13px Arial,sans-serif;color:#80868b">… ' + (alleFehler.length - 50) + ' weitere Fehler nicht angezeigt.</p>' : '')
  : '<p style="font:14px/1.5 Arial,sans-serif;color:#137333;margin:24px 0 0">Keine Fehler beim Schreiben der Preislisten.</p>';

const warnung = (bestandFehler.length || (gelesenAT === 0 && gelesenCH === 0))
  ? '<div style="background:#fef7e0;border-left:4px solid #f9ab00;padding:12px 16px;margin:0 0 20px;font:13px/1.5 Arial,sans-serif;color:#5f4200">'
    + '<b>Achtung:</b> Der bisherige Preisstand konnte nicht (vollständig) gelesen werden. '
    + 'Die Spalte „alt“ und damit die Einstufung geändert/unverändert ist dadurch unzuverlässig.'
    + (bestandFehler.length ? '<br>' + bestandFehler.slice(0, 5).map(esc).join('<br>') : '')
    + '</div>'
  : '';

const tabellenBlock = sortiert.length
  ? '<h3 style="font:600 15px/1.4 Arial,sans-serif;color:#202124;margin:28px 0 8px">Geänderte Preise'
    + (sortiert.length > MAX_ZEILEN
        ? ' <span style="font-weight:400;color:#80868b">(erste ' + MAX_ZEILEN + ' von ' + zahl(sortiert.length) + ', vollständig im CSV-Anhang)</span>'
        : ' <span style="font-weight:400;color:#80868b">(' + zahl(sortiert.length) + ')</span>')
    + '</h3>'
    + '<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%">'
    + '<tr><th style="' + TH + '">SKU</th><th style="' + TH + '">Titel</th><th style="' + TH + '">Typ</th>'
    + '<th style="' + TH + 'text-align:right">DE brutto</th><th style="' + TH + '">AT</th><th style="' + TH + '">CH</th></tr>'
    + zeilen
    + '</table>'
  : '<p style="font:14px/1.5 Arial,sans-serif;color:#5f6368;margin:24px 0 0">In beiden Katalogen hat sich kein Preis geändert.</p>';

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;color:#202124;max-width:960px">'
  + '<h2 style="font:600 20px/1.3 Arial,sans-serif;margin:0 0 4px">Katalogpreise AT &amp; CH – Report</h2>'
  + '<p style="font:13px/1.5 Arial,sans-serif;color:#5f6368;margin:0 0 20px">'
  + 'Shop <b>' + esc(config.shop) + '</b> &middot; Lauf beendet ' + esc(datumDe)
  + (dauerMin !== null ? ' &middot; Dauer ' + String(dauerMin).replace('.', ',') + ' Min' : '')
  + '</p>'
  + warnung
  + '<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%">'
  + '<tr><th style="' + TH + '">Katalog</th><th style="' + TH + 'text-align:right">Geprüft</th>'
  + '<th style="' + TH + 'text-align:right">Geändert</th><th style="' + TH + 'text-align:right">Neu</th>'
  + '<th style="' + TH + 'text-align:right">Unverändert</th><th style="' + TH + 'text-align:right">Bestand gelesen</th>'
  + '<th style="' + TH + 'text-align:right">Geschrieben</th><th style="' + TH + 'text-align:right">Fehler</th></tr>'
  + summeZeile('AT', stats.AT, rAT, gelesenAT, wAT)
  + summeZeile('CH', stats.CH, rCH, gelesenCH, wCH)
  + '</table>'
  + '<p style="font:12px/1.5 Arial,sans-serif;color:#80868b;margin:8px 0 0">'
  + '„Geändert“ = Preis oder Streichpreis in der Zielpreisliste weicht vom neu berechneten Wert ab. '
  + 'Streichpreise (compareAtPrice) sind durchgestrichen dargestellt. '
  + '„Neu“ = Variante war in der Preisliste noch nicht hinterlegt. '
  + 'Der Flow schreibt weiterhin alle Preise, gemeldet werden nur die Abweichungen.</p>'
  + tabellenBlock
  + fehlerBlock
  + '<p style="font:12px/1.5 Arial,sans-serif;color:#9aa0a6;margin:28px 0 0">'
  + 'Automatisch erzeugt von n8n · Workflow BB-Katalogpreise-AT-CH-aus-DE</p>'
  + '</div>';

const fehlerGesamt = alleFehler.length + bestandFehler.length;
const subject = (fehlerGesamt ? '⚠ ' : '')
  + 'Katalogpreise AT/CH – ' + zahl(sortiert.length) + ' Änderung' + (sortiert.length === 1 ? '' : 'en')
  + (fehlerGesamt ? ' · ' + fehlerGesamt + ' Fehler' : '')
  + ' (' + stempel + ')';

return [{
  json: {
    subject: subject,
    html: html,
    aenderungen: sortiert.length,
    fehler: fehlerGesamt,
    stats: stats,
    geschriebenAT: rAT.geschrieben,
    geschriebenCH: rCH.geschrieben,
    dauerMin: dauerMin
  },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: 'katalogpreise-at-ch-' + stempel + '.csv',
      fileExtension: 'csv'
    }
  }
}];

// ===== DRY-RUN-VORSCHAU (inkl. Streichpreis) =====
// Hinter "AT Batches bauen" bzw. "CH Batches bauen" haengen (dieselbe Node zweimal,
// der Katalog wird automatisch aus der priceListId der eingehenden Items erkannt).
// WICHTIG: dafuer die Verbindung "... Batches bauen" -> "... Split in Batches" trennen,
// sonst wird trotzdem geschrieben.
// Schreibt nichts nach Shopify. Item 1 = Zusammenfassung, danach eine Zeile je Variante.

const NUR_AENDERUNGEN = true;  // false = auch unveraenderte Varianten auflisten
const MAX_ZEILEN      = 0;     // 0 = alle Zeilen

const eingang = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global');
const config = $('Config + Array leeren').first().json.config;

// --- Katalog bestimmen
const priceListId = eingang.length ? eingang[0].priceListId : null;
let land = null;
for (const k of Object.keys(config.priceLists)) {
  if (config.priceLists[k].id === priceListId) land = k;
}
if (!land) {
  throw new Error('Katalog nicht erkennbar: priceListId "' + priceListId
    + '" passt zu keiner Preisliste in der Config. Haengt die Node hinter "AT Batches bauen" oder "CH Batches bauen"?');
}

const waehrung = config.priceLists[land].currency;
const bestand = (sd.bestand && sd.bestand[land]) || {};
const bestandVgl = (sd.bestandVgl && sd.bestandVgl[land]) || {};
const bestandGelesen = Object.keys(bestand).length;
const bestandMitStreichpreis = Object.values(bestandVgl).filter(v => v !== null && v !== undefined).length;

// --- Stammdaten (Titel/Typ/DE-Preise) je Variante nachschlagen
const stamm = {};
for (const i of $('Preise berechnen (AT + CH)').all()) {
  stamm[i.json.variantId] = i.json;
}

const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const leer = (v) => (v === undefined || v === null) ? null : v;
const gleich = (a, b) => Math.abs(a - b) < 0.005;
// Streichpreise: beide leer = gleich, nur einer leer = abweichend
const gleichVgl = (a, b) => (a === null || b === null) ? a === b : gleich(a, b);
const vglArt = (alt, neu) => {
  if (alt === null && neu === null) return 'keiner';
  if (alt === null) return 'kommt hinzu';
  if (neu === null) return 'entfaellt';
  return gleich(alt, neu) ? 'unveraendert' : 'geaendert';
};

const zeilen = [];
const verdaechtig = [];
const z = {
  geaendert: 0, nurVK: 0, nurStreichpreis: 0, vkUndStreichpreis: 0,
  neu: 0, unveraendert: 0, ohnePreis: 0, teurer: 0, guenstiger: 0,
  vglHinzu: 0, vglEntfaellt: 0, vglGeaendert: 0, mitStreichpreisNeu: 0
};
let summeAlt = 0, summeNeu = 0;

for (const e of eingang) {
  const neuPreis = parseFloat(e.price && e.price.amount);
  if (!isFinite(neuPreis)) { z.ohnePreis++; continue; }
  const neuVglRoh = parseFloat(e.compareAtPrice && e.compareAtPrice.amount);
  const neuVgl = isFinite(neuVglRoh) ? neuVglRoh : null;
  if (neuVgl !== null) z.mitStreichpreisNeu++;

  const s = stamm[e.variantId] || {};
  // Gegenprobe Gutscheine: nichts mit "Gutschein" im Titel sollte hier ankommen
  if (/gutschein/i.test(s.title || '')) {
    verdaechtig.push({ sku: e.sku || s.sku || '', titel: s.title, variantId: e.variantId });
  }

  const alt = bestand[e.variantId];
  const altVgl = leer(bestandVgl[e.variantId]);
  const istNeu = alt === undefined;
  const vkAnders = !istNeu && !gleich(alt, neuPreis);
  const vglAnders = !istNeu && !gleichVgl(altVgl, neuVgl);
  const art = istNeu ? (neuVgl === null ? 'keiner' : 'kommt hinzu') : vglArt(altVgl, neuVgl);

  let aenderung = null;
  if (istNeu) z.neu++;
  else if (vkAnders || vglAnders) {
    z.geaendert++;
    if (vkAnders && vglAnders) { aenderung = 'VK+Streichpreis'; z.vkUndStreichpreis++; }
    else if (vkAnders) { aenderung = 'VK'; z.nurVK++; }
    else { aenderung = 'Streichpreis'; z.nurStreichpreis++; }
    if (vkAnders) {
      summeAlt += alt;
      summeNeu += neuPreis;
      if (neuPreis > alt) z.teurer++; else z.guenstiger++;
    }
    if (art === 'kommt hinzu') z.vglHinzu++;
    else if (art === 'entfaellt') z.vglEntfaellt++;
    else if (art === 'geaendert') z.vglGeaendert++;
  } else {
    z.unveraendert++;
    if (NUR_AENDERUNGEN) continue;
  }

  zeilen.push({
    katalog: land,
    status: istNeu ? 'neu in Preisliste' : (aenderung ? 'wird geaendert' : 'unveraendert'),
    aenderung: aenderung,
    sku: e.sku || s.sku || '',
    titel: s.title || '',
    typ: s.typ || '',
    deBrutto: s.priceDEBrutto === undefined ? null : r2(s.priceDEBrutto),
    deStreichpreis: leer(s.compareAtDEBrutto),
    preisAktuell: istNeu ? null : r2(alt),
    preisNeu: r2(neuPreis),
    differenz: istNeu ? null : r2(neuPreis - alt),
    differenzProzent: (istNeu || !alt) ? null : Math.round((neuPreis / alt - 1) * 1000) / 10,
    streichpreisAktuell: altVgl === null ? null : r2(altVgl),
    streichpreisNeu: neuVgl === null ? null : r2(neuVgl),
    streichpreisAenderung: art,
    waehrung: waehrung,
    variantId: e.variantId
  });
}

// Reihenfolge: VK+Streichpreis, nur VK, nur Streichpreis, unveraendert, neu in Preisliste;
// innerhalb der Gruppe groesster VK-Sprung zuerst, dann SKU
const RANG = { 'VK+Streichpreis': 0, 'VK': 1, 'Streichpreis': 2 };
const rang = (r) => r.status === 'neu in Preisliste' ? 4 : (r.aenderung ? RANG[r.aenderung] : 3);
zeilen.sort((a, b) => {
  const ra = rang(a), rb = rang(b);
  if (ra !== rb) return ra - rb;
  const da = Math.abs(a.differenz || 0), db = Math.abs(b.differenz || 0);
  if (da !== db) return db - da;
  return String(a.sku).localeCompare(String(b.sku));
});

const gezeigt = MAX_ZEILEN > 0 ? zeilen.slice(0, MAX_ZEILEN) : zeilen;

// --- Uebersprungene Varianten (Bundles/Gutscheine) und ob sie noch in der Preisliste stehen
const uebersprungen = (sd.uebersprungen || []).map(u => ({
  grund: u.grund,
  sku: u.sku || '',
  titel: u.title,
  deBrutto: isFinite(u.priceDEBrutto) ? r2(u.priceDEBrutto) : null,
  preisInPreisliste: bestand[u.variantId] === undefined ? null : r2(bestand[u.variantId]),
  streichpreisInPreisliste: leer(bestandVgl[u.variantId]),
  variantId: u.variantId
}));
const zaehleGrund = (g) => uebersprungen.filter(u => u.grund === g).length;
const mitEintrag = (g) => uebersprungen.filter(u => u.grund === g && u.preisInPreisliste !== null).length;

const hinweise = [];
if (bestandGelesen === 0) hinweise.push('ACHTUNG: Kein Bestand gelesen - alles wird als "neu" gewertet. Bestand-Schleife pruefen (Scope/Fehler).');
if ((sd.bestandFehler || []).length) hinweise.push('ACHTUNG: Fehler beim Lesen der Preislisten, siehe bestandFehler.');
if (verdaechtig.length) hinweise.push('PRUEFEN: ' + verdaechtig.length + ' Variante(n) mit "Gutschein" im Titel wuerden geschrieben, siehe verdaechtigeGutscheinTitel.');
if (mitEintrag('gutschein')) hinweise.push('PRUEFEN: ' + mitEintrag('gutschein') + ' Gutschein-Variante(n) haben noch einen Preis in dieser Preisliste (Altlast, wird vom Flow nicht entfernt).');
hinweise.push(NUR_AENDERUNGEN ? 'Nur Abweichungen gelistet (NUR_AENDERUNGEN = true).' : 'Alle Varianten gelistet.');

const zusammenfassung = {
  zeile: '=== ZUSAMMENFASSUNG ' + land + ' (' + waehrung + ') ===',
  priceListId: priceListId,
  steuersaetze: { DE: config.tax.DE, [land]: config.tax[land] },
  variantenGesamt: eingang.length,
  wuerdenSichAendern: z.geaendert,
  davonNurVK: z.nurVK,
  davonNurStreichpreis: z.nurStreichpreis,
  davonVKundStreichpreis: z.vkUndStreichpreis,
  vkTeurer: z.teurer,
  vkGuenstiger: z.guenstiger,
  streichpreisKommtHinzu: z.vglHinzu,
  streichpreisEntfaellt: z.vglEntfaellt,
  streichpreisGeaendert: z.vglGeaendert,
  neuInPreisliste: z.neu,
  unveraendert: z.unveraendert,
  ohneGueltigenPreis: z.ohnePreis,
  mitStreichpreisNachLauf: z.mitStreichpreisNeu,
  bestandGelesen: bestandGelesen,
  bestandMitStreichpreis: bestandMitStreichpreis,
  bestandFehler: sd.bestandFehler || [],
  summeVKAktuellGeaenderte: r2(summeAlt),
  summeVKNeuGeaenderte: r2(summeNeu),
  differenzVKGesamt: r2(summeNeu - summeAlt),
  uebersprungenBundles: zaehleGrund('bundle'),
  uebersprungenGutscheine: zaehleGrund('gutschein'),
  bundlesMitEintragInPreisliste: mitEintrag('bundle'),
  gutscheineMitEintragInPreisliste: mitEintrag('gutschein'),
  verdaechtigeGutscheinTitel: verdaechtig,
  zeilenAngezeigt: gezeigt.length + (gezeigt.length < zeilen.length ? ' von ' + zeilen.length : ''),
  hinweis: hinweise.join(' | '),
  uebersprungenListe: uebersprungen
};

return [{ json: zusammenfassung }].concat(gezeigt.map((r, i) => ({ json: Object.assign({ zeile: i + 1 }, r) })));

// ===== DRY-RUN-VORSCHAU (inkl. Streichpreis) =====
// Hinter "AT Batches bauen" bzw. "CH Batches bauen" haengen (dieselbe Node zweimal,
// der Katalog wird automatisch aus der priceListId der eingehenden Items erkannt).
// WICHTIG: dafuer die Verbindung "... Batches bauen" -> "... Split in Batches" trennen,
// sonst wird trotzdem geschrieben.
// Schreibt nichts nach Shopify. Item 1 = Zusammenfassung, danach eine Zeile je Variante.

const NUR_AENDERUNGEN = true;  // false = auch unveraenderte Varianten auflisten
const MAX_ZEILEN      = 0;     // 0 = alle Zeilen

const eingang = $input.all().map(i => i.json);
const sd = $getWorkflowStaticData('global');
const config = $('Config + Array leeren').first().json.config;

// --- Katalog bestimmen
const priceListId = eingang.length ? eingang[0].priceListId : null;
