  if (config.priceLists[k].id === priceListId) land = k;
}
if (!land) {
  throw new Error('Katalog nicht erkennbar: priceListId "' + priceListId
    + '" passt zu keiner Preisliste in der Config. Haengt die Node hinter "AT Batches bauen" oder "CH Batches bauen"?');
}

const waehrung = config.priceLists[land].currency;
const bestand = (sd.bestand && sd.bestand[land]) || {};
const bestandVgl = (sd.bestandVgl && sd.bestandVgl[land]) || {};
const bestandGelesen = Object.keys(bestand).length;
const bestandMitStreichpreis = Object.values(bestandVgl).filter(v => v !== null && v !== undefined).length;

// --- Stammdaten (Titel/Typ/DE-Preise) je Variante nachschlagen
const stamm = {};
for (const i of $('Preise berechnen (AT + CH)').all()) {
  stamm[i.json.variantId] = i.json;
}

const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const leer = (v) => (v === undefined || v === null) ? null : v;
const gleich = (a, b) => Math.abs(a - b) < 0.005;
// Streichpreise: beide leer = gleich, nur einer leer = abweichend
const gleichVgl = (a, b) => (a === null || b === null) ? a === b : gleich(a, b);
const vglArt = (alt, neu) => {
  if (alt === null && neu === null) return 'keiner';
  if (alt === null) return 'kommt hinzu';
  if (neu === null) return 'entfaellt';
  return gleich(alt, neu) ? 'unveraendert' : 'geaendert';
};

const zeilen = [];
const verdaechtig = [];
const z = {
  geaendert: 0, nurVK: 0, nurStreichpreis: 0, vkUndStreichpreis: 0,
  neu: 0, unveraendert: 0, ohnePreis: 0, teurer: 0, guenstiger: 0,
  vglHinzu: 0, vglEntfaellt: 0, vglGeaendert: 0, mitStreichpreisNeu: 0
};
let summeAlt = 0, summeNeu = 0;

for (const e of eingang) {
  const neuPreis = parseFloat(e.price && e.price.amount);
  if (!isFinite(neuPreis)) { z.ohnePreis++; continue; }
  const neuVglRoh = parseFloat(e.compareAtPrice && e.compareAtPrice.amount);
  const neuVgl = isFinite(neuVglRoh) ? neuVglRoh : null;
  if (neuVgl !== null) z.mitStreichpreisNeu++;

  const s = stamm[e.variantId] || {};
  // Gegenprobe Gutscheine: nichts mit "Gutschein" im Titel sollte hier ankommen
  if (/gutschein/i.test(s.title || '')) {
    verdaechtig.push({ sku: e.sku || s.sku || '', titel: s.title, variantId: e.variantId });
  }

  const alt = bestand[e.variantId];
  const altVgl = leer(bestandVgl[e.variantId]);
  const istNeu = alt === undefined;
  const vkAnders = !istNeu && !gleich(alt, neuPreis);
  const vglAnders = !istNeu && !gleichVgl(altVgl, neuVgl);
  const art = istNeu ? (neuVgl === null ? 'keiner' : 'kommt hinzu') : vglArt(altVgl, neuVgl);

  let aenderung = null;
  if (istNeu) z.neu++;
  else if (vkAnders || vglAnders) {
    z.geaendert++;
    if (vkAnders && vglAnders) { aenderung = 'VK+Streichpreis'; z.vkUndStreichpreis++; }
    else if (vkAnders) { aenderung = 'VK'; z.nurVK++; }
    else { aenderung = 'Streichpreis'; z.nurStreichpreis++; }
    if (vkAnders) {
      summeAlt += alt;
      summeNeu += neuPreis;
      if (neuPreis > alt) z.teurer++; else z.guenstiger++;
    }
    if (art === 'kommt hinzu') z.vglHinzu++;
    else if (art === 'entfaellt') z.vglEntfaellt++;
    else if (art === 'geaendert') z.vglGeaendert++;
  } else {
    z.unveraendert++;
    if (NUR_AENDERUNGEN) continue;
  }

  zeilen.push({
    katalog: land,
    status: istNeu ? 'neu in Preisliste' : (aenderung ? 'wird geaendert' : 'unveraendert'),
    aenderung: aenderung,
    sku: e.sku || s.sku || '',
    titel: s.title || '',
    typ: s.typ || '',
    deBrutto: s.priceDEBrutto === undefined ? null : r2(s.priceDEBrutto),
    deStreichpreis: leer(s.compareAtDEBrutto),
    preisAktuell: istNeu ? null : r2(alt),
    preisNeu: r2(neuPreis),
    differenz: istNeu ? null : r2(neuPreis - alt),
    differenzProzent: (istNeu || !alt) ? null : Math.round((neuPreis / alt - 1) * 1000) / 10,
    streichpreisAktuell: altVgl === null ? null : r2(altVgl),
    streichpreisNeu: neuVgl === null ? null : r2(neuVgl),
    streichpreisAenderung: art,
    waehrung: waehrung,
    variantId: e.variantId
  });
}

// Reihenfolge: VK+Streichpreis, nur VK, nur Streichpreis, unveraendert, neu in Preisliste;
// innerhalb der Gruppe groesster VK-Sprung zuerst, dann SKU
const RANG = { 'VK+Streichpreis': 0, 'VK': 1, 'Streichpreis': 2 };
const rang = (r) => r.status === 'neu in Preisliste' ? 4 : (r.aenderung ? RANG[r.aenderung] : 3);
zeilen.sort((a, b) => {
  const ra = rang(a), rb = rang(b);
  if (ra !== rb) return ra - rb;
  const da = Math.abs(a.differenz || 0), db = Math.abs(b.differenz || 0);
  if (da !== db) return db - da;
  return String(a.sku).localeCompare(String(b.sku));
});

const gezeigt = MAX_ZEILEN > 0 ? zeilen.slice(0, MAX_ZEILEN) : zeilen;

// --- Uebersprungene Varianten (Bundles/Gutscheine) und ob sie noch in der Preisliste stehen
const uebersprungen = (sd.uebersprungen || []).map(u => ({
  grund: u.grund,
  sku: u.sku || '',
  titel: u.title,
  deBrutto: isFinite(u.priceDEBrutto) ? r2(u.priceDEBrutto) : null,
  preisInPreisliste: bestand[u.variantId] === undefined ? null : r2(bestand[u.variantId]),
  streichpreisInPreisliste: leer(bestandVgl[u.variantId]),
  variantId: u.variantId
}));
const zaehleGrund = (g) => uebersprungen.filter(u => u.grund === g).length;
const mitEintrag = (g) => uebersprungen.filter(u => u.grund === g && u.preisInPreisliste !== null).length;

const hinweise = [];
if (bestandGelesen === 0) hinweise.push('ACHTUNG: Kein Bestand gelesen - alles wird als "neu" gewertet. Bestand-Schleife pruefen (Scope/Fehler).');
if ((sd.bestandFehler || []).length) hinweise.push('ACHTUNG: Fehler beim Lesen der Preislisten, siehe bestandFehler.');
if (verdaechtig.length) hinweise.push('PRUEFEN: ' + verdaechtig.length + ' Variante(n) mit "Gutschein" im Titel wuerden geschrieben, siehe verdaechtigeGutscheinTitel.');
if (mitEintrag('gutschein')) hinweise.push('PRUEFEN: ' + mitEintrag('gutschein') + ' Gutschein-Variante(n) haben noch einen Preis in dieser Preisliste (Altlast, wird vom Flow nicht entfernt).');
hinweise.push(NUR_AENDERUNGEN ? 'Nur Abweichungen gelistet (NUR_AENDERUNGEN = true).' : 'Alle Varianten gelistet.');

const zusammenfassung = {
  zeile: '=== ZUSAMMENFASSUNG ' + land + ' (' + waehrung + ') ===',
  priceListId: priceListId,
  steuersaetze: { DE: config.tax.DE, [land]: config.tax[land] },
  variantenGesamt: eingang.length,
  wuerdenSichAendern: z.geaendert,
  davonNurVK: z.nurVK,
  davonNurStreichpreis: z.nurStreichpreis,
  davonVKundStreichpreis: z.vkUndStreichpreis,
  vkTeurer: z.teurer,
  vkGuenstiger: z.guenstiger,
  streichpreisKommtHinzu: z.vglHinzu,
  streichpreisEntfaellt: z.vglEntfaellt,
  streichpreisGeaendert: z.vglGeaendert,
  neuInPreisliste: z.neu,
  unveraendert: z.unveraendert,
  ohneGueltigenPreis: z.ohnePreis,
  mitStreichpreisNachLauf: z.mitStreichpreisNeu,
  bestandGelesen: bestandGelesen,
  bestandMitStreichpreis: bestandMitStreichpreis,
  bestandFehler: sd.bestandFehler || [],
  summeVKAktuellGeaenderte: r2(summeAlt),
  summeVKNeuGeaenderte: r2(summeNeu),
  differenzVKGesamt: r2(summeNeu - summeAlt),
  uebersprungenBundles: zaehleGrund('bundle'),
  uebersprungenGutscheine: zaehleGrund('gutschein'),
  bundlesMitEintragInPreisliste: mitEintrag('bundle'),
  gutscheineMitEintragInPreisliste: mitEintrag('gutschein'),
  verdaechtigeGutscheinTitel: verdaechtig,
  zeilenAngezeigt: gezeigt.length + (gezeigt.length < zeilen.length ? ' von ' + zeilen.length : ''),
  hinweis: hinweise.join(' | '),
  uebersprungenListe: uebersprungen
};

return [{ json: zusammenfassung }].concat(gezeigt.map((r, i) => ({ json: Object.assign({ zeile: i + 1 }, r) })));

// ===== JSON-DATEI ZUM HERUNTERLADEN =====
// Hinter "Vorschau (Dry-Run)" haengen (funktioniert aber mit beliebigen Items).
// Download in n8n: Node ausfuehren -> Ausgabe-Panel -> Tab "Binary" -> Download.

const PRETTY = true;   // false = kompakt, deutlich kleinere Datei

const items = $input.all().map(i => i.json);

// Zusammenfassungs-Item der Vorschau-Node von den Detailzeilen trennen
const istSummary = (o) => typeof o.zeile === 'string' && o.zeile.indexOf('===') === 0;
const zusammenfassung = items.find(istSummary) || null;
const zeilen = items.filter(o => !istSummary(o));

let katalog = 'unbekannt';
if (zusammenfassung && zusammenfassung.zeile) {
  const m = zusammenfassung.zeile.match(/ZUSAMMENFASSUNG\s+(\w+)/);
  if (m) katalog = m[1];
}
if (katalog === 'unbekannt' && zeilen.length && zeilen[0].katalog) katalog = zeilen[0].katalog;

const jetzt = new Date();
const stempel = jetzt.toISOString().slice(0, 19).replace(/[:T]/g, '-');

const inhalt = {
  erzeugt: jetzt.toISOString(),
  workflow: (typeof $workflow !== 'undefined' && $workflow) ? $workflow.name : null,
  katalog: katalog,
  anzahlZeilen: zeilen.length,
  zusammenfassung: zusammenfassung,
  zeilen: zeilen
};

const text = PRETTY ? JSON.stringify(inhalt, null, 2) : JSON.stringify(inhalt);
const buf = Buffer.from(text, 'utf8');
const dateiname = 'preisvorschau-' + katalog + '-' + stempel + '.json';

return [{
  json: {
    dateiname: dateiname,
    katalog: katalog,
    anzahlZeilen: zeilen.length,
    groesseKB: Math.round(buf.length / 102.4) / 10,
    hinweis: 'Download im Ausgabe-Panel unter "Binary".'
  },
  binary: {
    data: {
      data: buf.toString('base64'),
      mimeType: 'application/json',
      fileName: dateiname,
      fileExtension: 'json'
    }
  }
}];

